/* prog21_date_validator.c
 *
 * Reimplementation of the original binary's behaviour.
 * The program expects a single argument of the form YYYY-MM-DD.
 * It prints "VALID" if the argument represents a correct Gregorian date,
 * otherwise it prints "INVALID".
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>
#include <stdbool.h>

/* Return true if the given year is a leap year in the Gregorian calendar */
static bool is_leap(int year)
{
    if (year % 4 != 0) return false;
    if (year % 100 != 0) return true;
    return (year % 400 == 0);
}

/* Return the number of days in the given month of the given year */
static int days_in_month(int year, int month)
{
    static const int dim[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };
    if (month == 2 && is_leap(year))
        return 29;
    return dim[month - 1];
}

/* Validate the date string; returns true if it is a correct date */
static bool validate_date(const char *s)
{
    /* Length must be exactly 10 */
    if (strlen(s) != 10)
        return false;

    /* Check the fixed positions for '-' */
    if (s[4] != '-' || s[7] != '-')
        return false;

    /* All other characters must be digits */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (!isdigit((unsigned char)s[i]))
            return false;
    }

    /* Convert the three fields */
    int year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
                (s[2] - '0') * 10   + (s[3] - '0');
    int month = (s[5] - '0') * 10   + (s[6] - '0');
    int day   = (s[8] - '0') * 10   + (s[9] - '0');

    /* Basic range checks */
    if (month < 1 || month > 12)
        return false;
    if (day < 1)
        return false;

    /* Day must not exceed the maximum for the month */
    if (day > days_in_month(year, month))
        return false;

    return true;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    if (validate_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");

    return 0;
}
